SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.NAME AS oblname, Имена_станций.ordnumb, Станции2021.Year, Станции2021.NUST, Станции2021.nr, Станции2021.E, Станции2021.EOTP, Станции2021.EURT, Станции2021.EUST, Станции2021.Q, Станции2021.TURT, Станции2021.TUST, Станции2021.B, Станции2021.GAZ, Доп_угли2021.gaz_prir, Доп_угли2021.gazpp, Станции2021.MAZUT, Доп_угли2021.maztop, Доп_угли2021.gtt, Доп_угли2021.nft_proch, Доп_угли2021.disel, Станции2021.TORF, Станции2021.SLAN, Станции2021.ISK_GAZ, Доп_угли2021.domen_g, Доп_угли2021.koks_g, Доп_угли2021.prochgaz, Станции2021.PROCH, Доп_угли2021.tvproch, Доп_угли2021.szh_gaz, Доп_угли2021.inoe, Станции2021.UGOL, Станции2021.DON, Станции2021.PODM, Станции2021.PECH, Доп_угли2021.intin, Доп_угли2021.vork, Станции2021.ARKT, Станции2021.KUZN, Доп_угли2021.kuzngd, Доп_угли2021.kuznt, Доп_угли2021.kuznss, Доп_угли2021.kuznun, Станции2021.URAL, Доп_угли2021.sver, Доп_угли2021.chel, Доп_угли2021.kizel, Станции2021.BASHK, Станции2021.KAN, Доп_угли2021.nazar, Доп_угли2021.ibor, Доп_угли2021.berez, Доп_угли2021.per, Доп_угли2021.irbei, Доп_угли2021.kansk, Станции2021.TUNG, Доп_угли2021.jer, Доп_угли2021.karab, Станции2021.IRKUT, Доп_угли2021.azey, Доп_угли2021.mug, Доп_угли2021.cher, Станции2021.HAK, Станции2021.TUV, Станции2021.BUR, Доп_угли2021.gusin, Доп_угли2021.tugn, Доп_угли2021.okino, Станции2021.CHIT, Доп_угли2021.har, Доп_угли2021.urt, Доп_угли2021.tataur, Доп_угли2021.tarbag, Доп_угли2021.zab_kam, Станции2021.YAKUT, Доп_угли2021.neru, Доп_угли2021.zyryan, Доп_угли2021.pyak, Станции2021.AMUR, Доп_угли2021.rai, Доп_угли2021.erk, Доп_угли2021.ogodj, Станции2021.URG, Станции2021.USHUM, Станции2021.PRIM, Доп_угли2021.bikin, Доп_угли2021.razdol, Доп_угли2021.hankai, Станции2021.MAG, Станции2021.SAH, Станции2021.KAMCH, Станции2021.CHUKOT, Доп_угли2021.anad, Доп_угли2021.bering, Станции2021.KAZAH, Доп_угли2021.ekib, Доп_угли2021.maikub, Доп_угли2021.karag, Доп_угли2021.karajyra, Доп_угли2021.teniz, IIf(IsNull([TUV]),0,[TUV])+IIf(IsNull([URG]),0,[URG])+IIf(IsNull([MAG]),0,[MAG])+IIf(IsNull([KAMCH]),0,[KAMCH])+IIf(IsNull([tugn]),0,[tugn])+IIf(IsNull([cher]),0,[cher])+IIf(IsNull([jer]),0,[jer])+IIf(IsNull([karab]),0,[karab])+IIf(IsNull([vork]),0,[vork])+IIf(IsNull([intin]),0,[intin])+IIf(IsNull([kizel]),0,[kizel])+IIf(IsNull([zab_kam]),0,[zab_kam])+IIf(IsNull([ogodj]),0,[ogodj])+IIf(IsNull([razdol]),0,[razdol])+IIf(IsNull([neru]),0,[neru])+IIf(IsNull([zyryan]),0,[zyryan])+IIf(IsNull([pyak]),0,[pyak])+IIf(IsNull([kuzngd]),0,[kuzngd])+IIf(IsNull([kuznt]),0,[kuznt])+IIf(IsNull([kuznss]),0,[kuznss])+IIf(IsNull([kuznun]),0,[kuznun])+IIf(IsNull([bering]),0,[bering])+IIf(IsNull([ekib]),0,[ekib])+IIf(IsNull([karag]),0,[karag])+IIf(IsNull([karajyra]),0,[karajyra]) AS Kamennie, IIf(IsNull([PODM]),0,[PODM])+IIf(IsNull([BASHK]),0,[BASHK])+IIf(IsNull([USHUM]),0,[USHUM])+IIf(IsNull([SAH]),0,[SAH])+IIf(IsNull([nazar]),0,[nazar])+IIf(IsNull([ibor]),0,[ibor])+IIf(IsNull([berez]),0,[berez])+IIf(IsNull([per]),0,[per])+IIf(IsNull([irbei]),0,[irbei])+IIf(IsNull([kansk]),0,[kansk])+IIf(IsNull([gusin]),0,[gusin])+IIf(IsNull([okino]),0,[okino])+IIf(IsNull([azey]),0,[azey])+IIf(IsNull([mug]),0,[mug])+IIf(IsNull([sver]),0,[sver])+IIf(IsNull([chel]),0,[chel])+IIf(IsNull([har]),0,[har])+IIf(IsNull([urt]),0,[urt])+IIf(IsNull([tataur]),0,[tataur])+IIf(IsNull([tarbag]),0,[tarbag])+IIf(IsNull([rai]),0,[rai])+IIf(IsNull([erk]),0,[erk])+IIf(IsNull([svo]),0,[svo])+IIf(IsNull([bikin]),0,[bikin])+IIf(IsNull([hankai]),0,[hankai])+IIf(IsNull([anad]),0,[anad])+IIf(IsNull([maikub]),0,[maikub])+IIf(IsNull([teniz]),0,[teniz]) AS Burie, Станции2021.QOTR, Станции2021.SNK, Станции2021.EWTP, Станции2021.NT, Станции2021.OBOR, Станции2021.VED, Станции2021.OBL, Станции2021.DEP, Станции2021.OES, Станции2021.ER, Станции2021.NUMB1120, Имена_станций.Ведомство AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.FO, Имена_станций.форэм, Имена_станций.GK, Имена_станций.BE, имена_ГК.name AS namegk, [Филиалы ГК].name AS filial, IIf([obor]=20 Or [obor]=90,"ГТУ",IIf([obor]=21 Or [obor]=91,"ПГУ",IIf([obor]=22,"Диз",IIf([obor]=23,"ГУБТ",IIf([obor]=24 Or [obor]=89,"ГПА","ПСУ"))))) AS тип, Станции2021.SNt, Имена_станций.n1 AS [мощность блока], IIf([B]>0,[gaz]/[B]*100,0) AS dolya_gaz, IIf([B]>0,[ugol]/[B]*100,0) AS dolya_ugol, IIf([B]>0,[mazut]/[B]*100,0) AS dolya_mazut, IIf([B]>0,[torf]/[B]*100,0) AS dolya_torf, IIf([B]>0,[slan]/[B]*100,0) AS dolya_slan, IIf([B]>0,[proch]/[B]*100,0) AS dolya_proch, IIf([E]>0,[EWTP]/[E]*100,0) AS dolya_ewtp, IIf([Q]>0,[QOTR]/[Q]*100,0) AS dolya_qotr, IIf([B]>0 And [domen_g]>0,[domen_g]/[B]*100,0) AS dolya_domen_g, IIf([B]>0 And [koks_g]>0,[koks_g]/[B]*100,0) AS dolya_koks_g, IIf([B]>0 And [prochgaz]>0,[prochgaz]/[B]*100,0) AS dolya_prochgaz, IIf(([dolya_gaz]+[dolya_domen_g]+[dolya_koks_g]+[dolya_prochgaz])>=50,"gaz",IIf([dolya_ugol]>=50,"ugol","prochee")) AS Belyaev, [EUST]/[B] AS [dolya topl na ee], [TUST]/[B] AS [dolya topl na q], Имена_областей.Terr_Belyaev, IIf([E]>0,([E]-[EOTP])/[E]*100,0) AS [%_sn], IIf([Имена_станций].[BE]=9,"Пром.предпр.","Минэнерго") AS BLST_BE, IIf([Имена_станций].[Ведомство]=1,"Минэнерго","Пром.предпр.") AS BLST_V, IIf([Станции2021].[вед]=1,"Минэнерго","Пром.предпр.") AS BLST_ved
FROM ((Имена_станций INNER JOIN (Имена_областей RIGHT JOIN (Имена_ОЭС INNER JOIN (Станции2021 LEFT JOIN Доп_угли2021 ON (Станции2021.NUMB1120 = Доп_угли2021.NUMB1120) AND (Станции2021.YEAR = Доп_угли2021.YEAR)) ON Имена_ОЭС.oes = Станции2021.OES) ON Имена_областей.OBL = Станции2021.OBL) ON Имена_станций.NUMB = Станции2021.NUMB1120) LEFT JOIN имена_ГК ON Имена_станций.GK = имена_ГК.code) INNER JOIN [Филиалы ГК] ON Имена_станций.GKF = [Филиалы ГК].code;
